class Solution {
public:
    int uniquePaths(vector<vector<int>>& grid) {
        const int MOD=1000000007;
        int m=grid.size(),n=grid[0].size();
        vector<vector<int> > right(m,vector<int>(n,-1)),down=right;
        auto id=[&](int i,int j){return i*n+j;};
        for(int i=m-1;i>=0;i--)for(int j=n-1;j>=0;j--){
            if(grid[i][j]==0){right[i][j]=down[i][j]=id(i,j);}
            else{
                if(i+1<m)right[i][j]=down[i+1][j];
                if(j+1<n)down[i][j]=right[i][j+1];
            }
        }
        vector<vector<int> > dp(m,vector<int>(n));dp[0][0]=1;
        for(int i=0;i<m;i++)for(int j=0;j<n;j++){
            if(!dp[i][j])continue;
            if(j+1<n && right[i][j+1]>=0){int v=right[i][j+1];int &x=dp[v/n][v%n];x=(x+dp[i][j])%MOD;}
            if(i+1<m && down[i+1][j]>=0){int v=down[i+1][j];int &x=dp[v/n][v%n];x=(x+dp[i][j])%MOD;}
        }
        return dp[m-1][n-1];
    }
};
